class Solution:
    def confusingNumberII(self, n: int) -> int:
        mp = {'0':'0','1':'1','6':'9','8':'8','9':'6'}
        ans = 0
        for x in range(1, n + 1):
            s = str(x)
            if any(c not in mp for c in s):
                continue
            r = ''.join(mp[c] for c in reversed(s))
            if int(r) != x:
                ans += 1
        return ans

