class Solution {
    public int confusingNumberII(int n) {
        Map<Character,Character> mp = Map.of('0','0','1','1','6','9','8','8','9','6');
        int ans = 0;
        for (long x = 1; x <= n; x++) {
            String s = Long.toString(x);
            boolean ok = true;
            StringBuilder r = new StringBuilder();
            for (int i = s.length() - 1; i >= 0; i--) {
                Character d = mp.get(s.charAt(i));
                if (d == null) { ok = false; break; }
                r.append(d);
            }
            if (ok && Long.parseLong(r.toString()) != x) ans++;
        }
        return ans;
    }
}

