class Solution:
    def confusingNumberII(self, n: int) -> int:
        mp = {0:0, 1:1, 6:9, 8:8, 9:6}
        self.ans = 0

        def rotate(x):
            rev = 0
            while x > 0:
                rev = rev * 10 + mp[x % 10]
                x //= 10
            return rev

        def dfs(cur):
            if cur > 0 and rotate(cur) != cur:
                self.ans += 1
            for d in (0, 1, 6, 8, 9):
                nxt = cur * 10 + d
                if nxt == 0 or nxt > n:
                    continue
                dfs(nxt)

        dfs(0)
        return self.ans

