        long long rev = 0;
        while (x > 0) { rev = rev * 10 + mp[x % 10]; x /= 10; }
        return rev;
    }

    void dfs(long long cur) {
        if (cur > 0 && rotate(cur) != cur) ans++;
        int ds[] = {0,1,6,8,9};
        for (int d : ds) {
            long long nxt = cur * 10 + d;
            if (nxt == 0 || nxt > N) continue;
